package com.example.discovery.consumer.client;import com.example.discovery.consumer.config.ConsumerProperties;import com.example.discovery.consumer.model.ServiceInstance;import java.util.*;import org.springframework.core.ParameterizedTypeReference;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;@Component public class RegistryClient{private final RestClient restClient;private final ConsumerProperties p;public RegistryClient(RestClient restClient,ConsumerProperties p){this.restClient=restClient;this.p=p;} public List<ServiceInstance> discover(){var result=restClient.get().uri(p.registryUrl()+"/registry/services/{serviceName}",p.serviceName()).retrieve().body(new ParameterizedTypeReference<List<ServiceInstance>>(){});return result==null?List.of():result;}}
